// Export every Linear issue for team MM (including archived) to JSON + a stats summary.
// Read-only: uses the LINEAR_API_KEY from .env.local, GraphQL queries only.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";

const envLine = readFileSync(".env.local", "utf8")
  .split("\n")
  .find((l) => l.includes("LINEAR_API_KEY"));
if (!envLine) throw new Error("LINEAR_API_KEY not found in .env.local");
const API_KEY = envLine.replace(/^export\s+/, "").split("=").slice(1).join("=").trim().replace(/^["']|["']$/g, "");

const QUERY = `
query Issues($after: String) {
  issues(
    first: 25
    after: $after
    includeArchived: true
    filter: { team: { key: { eq: "MM" } } }
    orderBy: createdAt
  ) {
    pageInfo { hasNextPage endCursor }
    nodes {
      identifier title description url
      priority estimate dueDate
      createdAt updatedAt startedAt completedAt canceledAt archivedAt
      state { name type }
      labels { nodes { name } }
      project { name }
      projectMilestone { name }
      assignee { name }
      creator { name }
      parent { identifier }
      relations(first: 20) { nodes { type relatedIssue { identifier } } }
      attachments(first: 20) { nodes { title url } }
      comments(first: 50) { nodes { body createdAt user { name } } }
    }
  }
}`;

async function gql(variables) {
  const res = await fetch("https://api.linear.app/graphql", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: API_KEY },
    body: JSON.stringify({ query: QUERY, variables }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  const json = await res.json();
  if (json.errors) throw new Error(JSON.stringify(json.errors));
  return json.data.issues;
}

const issues = [];
let after = null;
for (;;) {
  const page = await gql({ after });
  issues.push(...page.nodes);
  process.stderr.write(`fetched ${issues.length}...\n`);
  if (!page.pageInfo.hasNextPage) break;
  after = page.pageInfo.endCursor;
}

// Flatten nested connection shapes for a stable archive format.
const flat = issues.map((i) => ({
  ...i,
  labels: i.labels.nodes.map((l) => l.name),
  relations: i.relations.nodes.map((r) => ({ type: r.type, issue: r.relatedIssue?.identifier })),
  attachments: i.attachments.nodes,
  comments: i.comments.nodes.map((c) => ({ author: c.user?.name, createdAt: c.createdAt, body: c.body })),
  state: i.state.name,
  stateType: i.state.type,
  project: i.project?.name ?? null,
  milestone: i.projectMilestone?.name ?? null,
  assignee: i.assignee?.name ?? null,
  creator: i.creator?.name ?? null,
  parent: i.parent?.identifier ?? null,
}));
flat.sort((a, b) => Number(a.identifier.split("-")[1]) - Number(b.identifier.split("-")[1]));

mkdirSync("linear-export", { recursive: true });
writeFileSync(
  "linear-export/mm-issues.json",
  JSON.stringify({ exportedAt: new Date().toISOString(), team: "MM", count: flat.length, issues: flat }, null, 2)
);

// Stats for the closeout analysis.
const active = flat.filter((i) => !i.archivedAt);
const byState = {};
for (const i of active) byState[i.state] = (byState[i.state] ?? 0) + 1;
const waves = {};
for (const i of flat) {
  for (const l of i.labels) {
    if (!l.startsWith("Wave")) continue;
    waves[l] ??= { total: 0, done: 0, canceled: 0, activeInLinear: 0, open: [] };
    waves[l].total++;
    if (i.stateType === "completed") waves[l].done++;
    else if (i.stateType === "canceled") waves[l].canceled++;
    else waves[l].open.push(i.identifier);
    if (!i.archivedAt) waves[l].activeInLinear++;
  }
}
const doneUnarchived = active.filter((i) => i.stateType === "completed" || i.stateType === "canceled").length;

const summary = {
  total: flat.length,
  archived: flat.length - active.length,
  activeCountedTowardLimit: active.length,
  doneOrCanceledButUnarchived: doneUnarchived,
  activeAfterArchivingDone: active.length - doneUnarchived,
  byState,
  waves,
};
writeFileSync("linear-export/summary.json", JSON.stringify(summary, null, 2));
console.log(JSON.stringify(summary, null, 2));

