function isDeviceKeyRoot(
  didDoc: Record<string, unknown>,
  deviceKeyId: string
): boolean | null {
  const rotationKeys = didDoc.rotationKeys;
  if (!Array.isArray(rotationKeys) || rotationKeys.length === 0) return null;
  return rotationKeys[0] === deviceKeyId;
}

